import six
from abc import ABCMeta, abstractmethod
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class FileLogReader(object):
    def __init__(
            self,
            file_path,
            logreader_cls,
            logreader_kwargs,
            **kwargs):
        super(FileLogReader, self).__init__(**kwargs)
        self._file_path = file_path
        self._logreader_cls = logreader_cls
        self._logreader_kwargs = logreader_kwargs

    @staticmethod
    def _open(file_path):
        return open(file_path, "rb")

    def __iter__(self):
        with self._open(self._file_path) as file_obj:
            for log_entry in self._logreader_cls(
                    file_obj=file_obj,
                    **self._logreader_kwargs):
                yield log_entry


@six.add_metaclass(ABCMeta)
class LogReader(object):
    """Top-level base class for log readers handling a single file.

    """

    file_log_reader_cls = FileLogReader

    def __init__(self, file_obj, timezone="utc", **kwargs):
        """Initialize a log reader

        :param file file_obj: file object

        """
        super(LogReader, self).__init__(**kwargs)
        self._file_obj = file_obj
        self._timezone = timezone

    @abstractmethod
    def __iter__(self):
        """Yields the next log entry."""
        pass

    @classmethod
    def from_file(cls, file_path, **kwargs):
        """
        Create a log reader from a file path.

        :param file_path: path of the file

        :return: a FileLogReader

        The log reader is wrapped in a FileLogReader object to
        allow the following usage:

        .. code-block:: python

            for log_entry in ...LogReader.from_file(file_path="...", ...):
        """
        return cls.file_log_reader_cls(
            file_path=file_path,
            logreader_cls=cls,
            logreader_kwargs=kwargs)
